changeSet.sql:
ALTER TABLE lib_books ADD COLUMN content_kind VARCHAR(20);
UPDATE lib_books b SET content_kind = CASE WHEN EXISTS(SELECT 1 FROM lib_pages p WHERE p.book_id = b.id AND p.text_content IS NOT NULL AND btrim(p.text_content) <> '') AND ( (b.metadata->'pdf_links'->'files') IS NOT NULL AND jsonb_array_length(b.metadata->'pdf_links'->'files') > 0 OR EXISTS(SELECT 1 FROM library_files f WHERE f.book_id = b.id AND f.source_type = 'USER_UPLOAD' AND f.deleted_at IS NULL) ) THEN 'TEXT_AND_FILE' WHEN EXISTS(SELECT 1 FROM lib_pages p WHERE p.book_id = b.id AND p.text_content IS NOT NULL AND btrim(p.text_content) <> '') THEN 'TEXT_ONLY' WHEN ( (b.metadata->'pdf_links'->'files') IS NOT NULL AND jsonb_array_length(b.metadata->'pdf_links'->'files') > 0 OR EXISTS(SELECT 1 FROM library_files f WHERE f.book_id = b.id AND f.source_type = 'USER_UPLOAD' AND f.deleted_at IS NULL) ) THEN 'FILE_ONLY' ELSE 'TEXT_ONLY' END;
ALTER TABLE lib_books ALTER COLUMN content_kind SET DEFAULT 'TEXT_ONLY'; ALTER TABLE lib_books ALTER COLUMN content_kind SET NOT NULL; ALTER TABLE lib_books ADD CONSTRAINT lib_books_content_kind_check CHECK (content_kind IN ('TEXT_ONLY','TEXT_AND_FILE','FILE_ONLY'));
CREATE INDEX idx_lib_books_content_kind ON lib_books(content_kind);
